import datetime, json
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
def biz(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nxt(d):
    d = d + datetime.timedelta(1)
    while not biz(d):
        d = d + datetime.timedelta(1)
    return d
def nth(d, n):
    while n > 0:
        d = nxt(d)
        n -= 1
    return d
def load():
    for k in ('products', 'account_response.data.products', 'get_account_response.data.products'):
        v = vars.get(k)
        if isinstance(v, str) and v.strip().startswith('['):
            try:
                v = json.loads(v)
            except Exception:
                v = None
        if isinstance(v, list) and v:
            return v
    out = []
    for pre in ('account_response.data.products.', 'get_account_response.data.products.', 'products.'):
        i = 0
        while vars.get(pre + str(i) + '.product_id') is not None:
            p = dict()
            for f in ('product_id', 'type', 'card_last4', 'past_due', 'days_late', 'minimum_payment', 'instalment_amount'):
                if vars.get(pre + str(i) + '.' + f) is not None:
                    p[f] = vars.get(pre + str(i) + '.' + f)
            out.append(p)
            i += 1
        if out:
            break
    return out
def money(x):
    return '%.2f' % float(x)
def day(d):
    return d.strftime('%A') + ' ' + d.isoformat()
try:
    prods = load()
    now = str(vars.get('now') or '')
    today = datetime.date.fromisoformat(now[:10])
    fri = today + datetime.timedelta(4 - today.weekday()) if today.weekday() < 5 else today
    while not biz(fri) and fri > today:
        fri = fri - datetime.timedelta(1)
    if fri <= today or not biz(fri):
        fri = today + datetime.timedelta(7 - today.weekday() + 4)
        while not biz(fri):
            fri = fri - datetime.timedelta(1)
    plan = dict()
    lines = []
    last = today
    for p in prods:
        pid = str(p.get('product_id'))
        typ = str(p.get('type'))
        late = int(float(p.get('days_late') or 0))
        full = float(p.get('past_due') or 0)
        if typ == 'credit_card':
            name = 'credit card ending ' + str(p.get('card_last4') or '')
            floor = float(p.get('minimum_payment') or full)
            fname = 'minimum payment'
        else:
            name = 'personal loan' if typ == 'personal_loan' else 'car loan'
            floor = float(p.get('instalment_amount') or full)
            fname = 'instalment amount'
        early = late <= 7
        dl = nth(today, 12 if early else 7)
        if dl > last:
            last = dl
        a1 = fri if fri <= dl else dl
        dates = []
        d = today
        while d <= dl:
            if biz(d):
                dates.append(d.isoformat())
            d = d + datetime.timedelta(1)
        plan[pid] = dict(full=full, floor=floor, dates=dates, name=name)
        offers = 'persuasion offer 1 = payment on %s of the full amount %s, unless the customer already said the full amount is too much: then of the floor %s instead (ONE offer, never both)' % (day(a1), money(full), money(floor))
        if early:
            offers += '. This product has exactly ONE persuasion offer in total: when it is refused, offer nothing else for this product, not the floor and not another date'
        else:
            offers += '; persuasion offer 2 (the last one) = the floor %s on the deadline %s. This product has exactly TWO persuasion offers in total' % (money(floor), day(dl))
        offers += '. Floor offer date when the full amount is too much: %s' % day(a1)
        lines.append('- product_id %s: %s. Past due (full amount): %s. Days late: %d. Floor (%s): %s. Deadline, the latest date that can be recorded: %s. Allowed amounts: %s to %s. After a flat refusal: %s.' % (pid, name, money(full), late, fname, money(floor), day(dl), money(floor), money(full), offers))
    cal = []
    d = today
    while d <= last:
        if biz(d):
            cal.append(day(d) + ': business day')
        else:
            cal.append(day(d) + ': %s, NOT allowed, next business day is %s' % ('bank holiday' if d.weekday() < 5 else 'weekend', day(nxt(d))))
        d = d + datetime.timedelta(1)
    vars['plan_json'] = json.dumps(plan)
    vars['debt_facts'] = '\n'.join(lines) if lines else 'The account could not be read. Say you do not have that information.'
    vars['calendar'] = 'Today is %s.\n' % day(today) + '\n'.join(cal)
    vars['product_count'] = str(len(prods))
    if len(prods) > 1:
        vars['first_ask'] = 'ask whether the customer can pay all of them today. If not, go through the products one by one in the order listed; do not ask about today again for each product: each product starts directly at its persuasion offer 1, and refusals are counted per product'
    else:
        vars['first_ask'] = 'ask exactly: "Can you make this payment today?"'
except Exception:
    vars['plan_json'] = ''
    vars['debt_facts'] = 'The account could not be read. Say you do not have that information.'
    vars['calendar'] = ''
    vars['product_count'] = '1'
    vars['first_ask'] = 'ask exactly: "Can you make this payment today?"'
vars['promised_ids'] = ','
vars['notes_log'] = ''
vars['transfer_done'] = 'no'

def g(k):
    v = vars.get(k)
    return '' if v is None else str(v)
try:
    out, why, bye = 'not_reached', 'unclear', 'I could not confirm who I am speaking with. Thank you for your time. Goodbye.'
    line = g('line_status')
    tp = g('tp_status')
    verified = g('verify_identity_response.data.all_verified').lower() == 'true'
    queue = g('transfer_to_agent_args.queue') or g('transfer_to_agent_args.body.queue')
    transferred = g('transfer_done') == 'yes' or g('transfer_to_agent_response.data.ok').lower() == 'true'
    promised = int(float(g('promise_count') or 0))
    if promised == 0 and g('create_promise_response.data.ok').lower() == 'true' and not g('promise_count'):
        promised = 1
    sms = 'You will receive a text message confirming this promise. ' if promised > 0 else ''
    if transferred:
        if not verified:
            queue = 'general'
        out, why = 'transferred', dict(restructuring='restructuring', support='support').get(queue, 'human')
        bye = sms + 'I am transferring you to a colleague now. Thank you for your time. Goodbye.'
    elif not verified:
        if tp == 'deceased' or line == 'deceased':
            out, why, bye = 'not_reached', 'deceased', 'I am sorry for your loss. Goodbye.'
        elif tp == 'wrong_number' or line == 'wrong_number':
            out, why, bye = 'not_reached', 'wrong_number', 'I apologise for the disturbance. Thank you for your time. Goodbye.'
        elif line == 'other_person':
            if g('schedule_callback_response.data.ok').lower() == 'true':
                out, why, bye = 'not_reached', 'callback', 'Thank you, we will call back at that time. Goodbye.'
            else:
                out, why, bye = 'not_reached', 'no_callback', 'I am not able to arrange a callback for that time. Thank you for your time. Goodbye.'
        elif line == 'customer':
            if g('verify_identity_response.data.wrong_answers_left') == '0':
                out, why, bye = 'not_verified', 'failed', 'I could not verify your identity, so I cannot continue on this call. Please use the mobile app or visit a branch. Thank you for your time. Goodbye.'
            else:
                out, why, bye = 'not_verified', 'declined', 'I understand. Without the security questions I cannot continue. Thank you for your time. Goodbye.'
    elif promised > 0:
        out, why, bye = 'promise', '', sms + 'Thank you for your time. Goodbye.'
    else:
        notes = [x.split(':')[1] for x in g('notes_log').split(';') if ':' in x]
        if not notes and g('add_note_args.reason'):
            notes = [g('add_note_args.reason')]
        rest = [n for n in notes if n != 'paid']
        if notes and not rest:
            out, why, bye = 'paid', '', 'Payments can take one business day to appear. Thank you for your time. Goodbye.'
        else:
            why = rest[0] if rest and rest[0] in ('refused', 'hardship', 'dispute', 'service_error') else 'refused'
            out, bye = 'no_promise', 'Thank you for your time. Goodbye.'
    vars['outcome'] = out
    vars['reason'] = why
    vars['farewell'] = bye
except Exception:
    pass

